-- The subject exposes one function and only an always-refusing CheckResult.
-- This oracle literalizes the Cabal version and every limit.  Its primary wire
-- vectors are pinned bytes; multiplicity builders are used only for separately
-- stated resource boundaries.

runCompilerBuildInfoOracle :: IO ()
runCompilerBuildInfoOracle =
  finishDiagnostics
    "CompilerBuildInfoOracle"
    ( fixtureIntegrityProblems
        <> mutationIntentProblems
        <> problemConstructorInventoryProblems
        <> opacityInventoryProblems
        <> concatMap exactCaseProblems allExactCases
    )

-- Run the one independently named exact case assigned to a selector.  The
-- matrix invokes the isolation runner from the same linked executable to keep
-- every other exact case as an executed unaffected control.
runCompilerBuildInfoSelectorOracle :: String -> IO ()
runCompilerBuildInfoSelectorOracle selector =
  case (selectorTargets selector, selectorCases selector) of
    ([target], [assigned]) -> do
      let controlProblems =
            fixtureIntegrityProblems
              <> mutationIntentProblems
              <> problemConstructorInventoryProblems
              <> opacityInventoryProblems
          assignedProblems = exactCaseProblems assigned
      unless (null controlProblems) $ failDiagnostic "unaffected-control" controlProblems
      unless (null assignedProblems) $
        failDiagnostic ("assigned-locus:" <> target) (summarizeProblemLabels assignedProblems)
    (targets, cases) ->
      failDiagnostic "unresolvable-selector"
        [ "selector=" <> selector
        , "targets=" <> show targets
        , "exact-case-count=" <> show (length cases)
        ]

runCompilerBuildInfoSelectorImpactOracle :: String -> IO ()
runCompilerBuildInfoSelectorImpactOracle selector =
  case (selectorTargets selector, selectorCases selector, selectorAffectedCases selector) of
    ([target], [_], affected) -> do
      let controlProblems =
            fixtureIntegrityProblems
              <> mutationIntentProblems
              <> problemConstructorInventoryProblems
              <> opacityInventoryProblems
          missingImpacts =
            [ "declared impacted exact case remained green: selector="
                <> selector
                <> "; exact-case="
                <> exactCaseLabel candidate
            | candidate <- affected
            , null (exactCaseProblems candidate)
            ]
      unless (null controlProblems) $ failDiagnostic "impact-control" controlProblems
      unless (null missingImpacts) $ failDiagnostic "declared-impact" missingImpacts
      unless (length affected == length (selectorAffectedTargets selector)) $
        failDiagnostic "declared-impact-resolution"
          ["selector=" <> selector <> "; primary=" <> target]
    (targets, cases, affected) ->
      failDiagnostic "unresolvable-selector"
        [ "selector=" <> selector
        , "targets=" <> show targets
        , "exact-case-count=" <> show (length cases)
        , "affected-case-count=" <> show (length affected)
        ]

runCompilerBuildInfoSelectorIsolationOracle :: String -> IO ()
runCompilerBuildInfoSelectorIsolationOracle selector = do
  let controlProblems =
        fixtureIntegrityProblems
          <> mutationIntentProblems
          <> problemConstructorInventoryProblems
          <> opacityInventoryProblems
      unaffectedProblems = concatMap exactCaseProblems (unaffectedSelectorCases selector)
      problems = controlProblems <> unaffectedProblems
  unless (null problems) $
    failDiagnostic "unaffected-control" (summarizeProblemLabels problems)

runCompilerBuildInfoSelectorProductControlOracle :: String -> IO ()
runCompilerBuildInfoSelectorProductControlOracle selector =
  case selectorTargets selector of
    [_]
      | selector ==
          "VALIDATION_COMPILER_BUILDINFO_DIAGNOSTIC_CHECK_NAME_PROJECTION_MUTANT" ->
          unless
            (take 1 (checkObservations observed)
              == [Observation "expected.compiler.flavour" "ghc"]) $
            failDiagnostic
              "product-control"
              [ "selector=" <> selector
              , "expected the independent compiler-flavour observation; observed="
                  <> show (take 1 (checkObservations observed))
              ]
      | otherwise ->
      unless (checkName observed == "compiler-build-info-diagnostic") $
        failDiagnostic
          "product-control"
          [ "selector=" <> selector
          , "expected check name compiler-build-info-diagnostic; observed="
              <> show (checkName observed)
          ]
    targets ->
      failDiagnostic "product-control-unresolvable"
        ["selector=" <> selector <> "; targets=" <> show targets]
 where
  observed = runDiagnostic expectedCompiler [mainIdentity] positiveBytes

unaffectedSelectorCases :: String -> [ExactCase]
unaffectedSelectorCases selector =
  [ candidate
  | candidate <- allExactCases
  , exactCaseLabel candidate `notElem` selectorAffectedTargets selector
  ]

summarizeProblemLabels :: [String] -> [String]
summarizeProblemLabels = uniqueStrings . map (takeWhile (/= ':'))

uniqueStrings :: [String] -> [String]
uniqueStrings = go []
 where
  go _ [] = []
  go seen (value : remaining)
    | value `elem` seen = go seen remaining
    | otherwise = value : go (value : seen) remaining

failDiagnostic :: String -> [String] -> IO ()
failDiagnostic label problems =
  fail (unlines (("CompilerBuildInfoOracle " <> label <> ":") : map ("  " <>) problems))

compilerBuildInfoSelectorNames :: [String]
compilerBuildInfoSelectorNames = map fst mutationIntent

selectorTargets :: String -> [String]
selectorTargets selector =
  [target | (candidate, target) <- mutationIntent, candidate == selector]

selectorCases :: String -> [ExactCase]
selectorCases selector =
  [ candidate
  | target <- selectorTargets selector
  , candidate <- allExactCases
  , exactCaseLabel candidate == target
  ]

selectorAffectedTargets :: String -> [String]
selectorAffectedTargets selector =
  selectorTargets selector
    <> concat [targets | (candidate, targets) <- mutationImpactIntent, candidate == selector]

selectorAffectedCases :: String -> [ExactCase]
selectorAffectedCases selector =
  [ candidate
  | target <- selectorAffectedTargets selector
  , candidate <- allExactCases
  , exactCaseLabel candidate == target
  ]

data ExactCase = ExactCase
  { exactCaseLabel :: String
  , exactCaseProblems :: [String]
  }

allExactCases :: [ExactCase]
allExactCases =
  concat
    [ positiveCases
    , expectationCases
    , schemaAndIdentityCases
    , argumentCases
    , pathCases
    , duplicateCases
    , constructorCases
    , schemaPredicateCases
    , jsonGrammarCases
    , grammarConjunctionCases
    , orderingCases
    , identityConstructorCases
    , identityLimitCases
    , closedAlternativeCases
    , resourceCases
    , resultEnvelopeCases
    ]

