mutationImpactIntent :: [(String, [String])]
mutationImpactIntent =
  mergeMutationImpactIntent
    ( baseMutationImpactIntent
        <> serializerMutationImpactIntent
        <> carrierMutationImpactIntent
        <> parserDecoderMutationImpactIntent
        <> argumentStateMutationImpactIntent
        <> helperMutationImpactIntent
        <> finalAuditMutationImpactIntent
        <> genericRouteMutationImpactIntent
    )
    integratedCensusMutationImpactIntent

mergeMutationImpactIntent
  :: [(String, [String])]
  -> [(String, [String])]
  -> [(String, [String])]
mergeMutationImpactIntent primary supplemental =
  [ (selector, targets)
  | (selector, _) <- mutationIntent
  , let targets = mergedTargets selector
  , not (null targets)
  ]
 where
  mergedTargets selector =
    concatMap (take 1)
      . group
      . sort
      $ [ target
        | (candidate, targets) <- primary <> supplemental
        , candidate == selector
        , target <- targets
        ]

