-- These serializer subjects share already closed observation routes.  The
-- census-owned grouping below is explicit and bounded; prototype lookup only
-- reuses oracle-owned exact-case labels and never reads production data.
serializerMutationImpactIntent :: [(String, [String])]
serializerMutationImpactIntent = concat
  [ impactRows commonObservationWithoutPayloadOverflowSelectors
      (filter (/= resultPayloadOverflowCase) commonObservationImpactTargets)
  , impactRows commonObservationSelectors commonObservationImpactTargets
  , impactRows expectedFieldSelectors expectedFieldImpactTargets
  , impactRows expectedComponentCountSelectors expectedComponentCountImpactTargets
  , impactRows generatedObservationSelectors generatedObservationImpactTargets
  , impactRows packageObservationSelectors packageObservationImpactTargets
  , impactRows pathObservationSelectors pathObservationImpactTargets
  , impactRows optionalPathIndexSelectors optionalPathIndexImpactTargets
  , impactRows standaloneKindSelectors standaloneKindImpactTargets
  , impactRows cabalPresentObservationSelectors cabalPresentObservationImpactTargets
  , impactRows pathOptionIndexValueSelectors pathOptionIndexValueImpactTargets
  ]

impactRows :: [String] -> [String] -> [(String, [String])]
impactRows selectors targets = [(selector, targets) | selector <- selectors]

prototypeImpacts :: String -> [String]
prototypeImpacts selector =
  concat
    [ targets
    | (candidate, targets) <- baseMutationImpactIntent
    , candidate == selector
    ]

commonObservationImpactTargets :: [String]
commonObservationImpactTargets =
  filter
    (/= resultEntryOverflowCase)
    (prototypeImpacts
      "VALIDATION_COMPILER_BUILDINFO_BODY_OBSERVED_REFUSAL_ROUTE_MUTANT")

expectedFieldImpactTargets :: [String]
expectedFieldImpactTargets =
  filter
    (/= resultEntryOverflowCase)
    (prototypeImpacts
      "VALIDATION_COMPILER_BUILDINFO_EXPECTED_COMPILER_FLAVOUR_OBSERVATION_DROP_MUTANT")

expectedComponentCountImpactTargets :: [String]
expectedComponentCountImpactTargets =
  filter
    (`notElem` [resultEntryOverflowCase, resultPayloadOverflowCase])
    (prototypeImpacts
      "VALIDATION_COMPILER_BUILDINFO_EXPECTED_COMPONENT_COUNT_OBSERVATION_DROP_MUTANT")

resultEntryOverflowCase :: String
resultEntryOverflowCase =
  "one result entry over the envelope refuses before the expanded projection is materialized"

