mutationIntentProblems :: [String]
mutationIntentProblems =
  [ "expected 614 mutation-intent rows, observed " <> show (length mutationIntent)
  | length mutationIntent /= 614
  ]
    <> ["duplicate mutation-intent selector " <> selector
       | selector <- duplicates (map fst mutationIntent)]
    <> ["unbounded mutation-intent selector " <> selector
       | (selector, _) <- mutationIntent, null selector || length selector > 128]
    <> ["unbounded mutation-intent target for " <> selector
       | (selector, target) <- mutationIntent, null target || length target > 128]
    <> ["duplicate exact-case label " <> label
       | label <- duplicates (map exactCaseLabel allExactCases)]
    <> ["mutation-intent target must name exactly one executable exact case: "
          <> selector <> " -> " <> target <> "; observed " <> show count
       | (selector, target) <- mutationIntent
       , let count = length
              [() | candidate <- allExactCases, exactCaseLabel candidate == target]
       , count /= 1]
    <> [ "expected 401 dependent-impact rows, observed "
          <> show (length mutationImpactIntent)
       | length mutationImpactIntent /= 401
       ]
    <> ["duplicate dependent-impact selector " <> selector
       | selector <- duplicates (map fst mutationImpactIntent)]
    <> [ "dependent-impact selector must name exactly one primary intent: "
          <> selector
          <> "; observed "
          <> show count
       | (selector, _) <- mutationImpactIntent
       , let count = length [() | (candidate, _) <- mutationIntent, candidate == selector]
       , count /= 1
       ]
    <> [ "dependent-impact exact case is duplicated within selector: "
          <> selector
          <> " -> "
          <> target
       | (selector, targets) <- mutationImpactIntent
       , target <- duplicates targets
       ]
    <> [ "dependent-impact repeats its selector's primary exact case: "
          <> selector
          <> " -> "
          <> target
       | (selector, targets) <- mutationImpactIntent
       , target <- targets
       , target `elem` [primary | (candidate, primary) <- mutationIntent, candidate == selector]
       ]
    <> [ "dependent-impact target must name exactly one executable exact case: "
          <> selector
          <> " -> "
          <> target
          <> "; observed "
          <> show count
       | (selector, targets) <- mutationImpactIntent
       , target <- targets
       , let count = length [() | candidate <- allExactCases, exactCaseLabel candidate == target]
       , count /= 1
       ]



